module ApplicationCable
  class Connection < ActionCable::Connection::Base
    def browser_key
      cookies.signed[:quizzy_browser]
    end
  end
end
class ApplicationController < ActionController::Base
end
module Moderate
  class BaseController < ApplicationController
    prepend_before_action :require_moderator
    before_action :no_store

    private
      def require_moderator
        name = ENV["QUIZZY_MODERATOR_USERNAME"]
        password = ENV["QUIZZY_MODERATOR_PASSWORD"]
        if name.present? && password.present?
          http_basic_authenticate_or_request_with name: name, password: password, realm: "Quizzy Moderator"
        else
          request_http_basic_authentication "Quizzy Moderator"
        end
      end
  end
end
